public with sharing class AccountOnboardingService {
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName
    ) {
        List<Account> accounts = new List<Account>();

        if (contactLastNamesByAccountName == null ||
            contactLastNamesByAccountName.isEmpty()) {
            return accounts;
        }

        fflib_SObjectUnitOfWork unitOfWork = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account accountRecord = new Account(Name = accountName);
            accounts.add(accountRecord);
            unitOfWork.registerNew(accountRecord);

            List<String> contactLastNames =
                contactLastNamesByAccountName.get(accountName);

            if (contactLastNames == null) {
                continue;
            }

            for (String contactLastName : contactLastNames) {
                Contact contactRecord = new Contact(
                    LastName = contactLastName
                );

                unitOfWork.registerNew(
                    contactRecord,
                    Contact.AccountId,
                    accountRecord
                );
            }
        }

        unitOfWork.commitWork();
        return accounts;
    }
}
