public with sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        fflib_SObjectUnitOfWork unitOfWork =
            (fflib_SObjectUnitOfWork) Application.UnitOfWork.newInstance();

        Integer closedCount = 0;
        Date closeDate = Date.today();

        for (Opportunity opportunity : opportunities) {
            if (opportunity.StageName == 'Closed Won') {
                continue;
            }

            opportunity.StageName = 'Closed Won';
            opportunity.CloseDate = closeDate;

            unitOfWork.registerDirty(opportunity);
            unitOfWork.registerPublishAfterSuccess(
                new Deal_Won__e(
                    Opportunity_Id__c = String.valueOf(opportunity.Id),
                    Amount__c = opportunity.Amount
                )
            );

            closedCount++;
        }

        unitOfWork.commitWork();
        return closedCount;
    }
}
