trigger CaseTrigger on Case (after update) {
    List<Id> newlyClosedCaseIds = new List<Id>();

    for (Case currentCase : Trigger.new) {
        Case previousCase = Trigger.oldMap.get(currentCase.Id);

        if (currentCase.IsClosed &&
            !previousCase.IsClosed &&
            currentCase.ContactId != null) {
            newlyClosedCaseIds.add(currentCase.Id);
        }
    }

    /*
     * A synchronous transaction can enqueue at most 50 Queueable jobs, so
     * enqueuing one job per Case cannot support the required 200-record API
     * batch. Chaining one job per Case can also exceed Queueable stack-depth
     * limits.
     *
     * Use bounded chunks instead. With the trigger batch limit of 200, this
     * enqueues at most four jobs. CaseSurveyJob uses partial DML so a Task
     * failure for one Case does not roll back successful Tasks for the other
     * Cases in the chunk.
     */
    Integer casesPerJob = CaseSurveyJob.CASES_PER_JOB;

    for (Integer startIndex = 0;
         startIndex < newlyClosedCaseIds.size();
         startIndex += casesPerJob) {

        Integer endIndex = Math.min(
            startIndex + casesPerJob,
            newlyClosedCaseIds.size()
        );

        List<Id> caseIdsForJob = new List<Id>();

        for (Integer index = startIndex; index < endIndex; index++) {
            caseIdsForJob.add(newlyClosedCaseIds[index]);
        }

        System.enqueueJob(new CaseSurveyJob(caseIdsForJob));
    }
}
