public inherited sharing class GiftImportService {
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        List<npsp__DataImport__c> stagedImports =
            new List<npsp__DataImport__c>();

        for (WebGift gift : gifts) {
            npsp__DataImport__c stagedImport = new npsp__DataImport__c(
                npsp__Donation_Donor__c = 'Contact1'
            );

            if (gift != null) {
                stagedImport.npsp__Contact1_Firstname__c = gift.firstName;
                stagedImport.npsp__Contact1_Lastname__c = gift.lastName;
                stagedImport.npsp__Contact1_Personal_Email__c = gift.email;
                stagedImport.npsp__Donation_Amount__c = gift.amount;
                stagedImport.npsp__Donation_Date__c = gift.giftDate;
            }

            stagedImports.add(stagedImport);
        }

        insert stagedImports;

        // The NPSP API reads the applicable hierarchy Data Import Settings
        // internally and processes each staged row independently.
        npsp.BDI_DataImport_API dataImportApi =
            new npsp.BDI_DataImport_API();
        dataImportApi.processDataImport(stagedImports);

        Map<Id, npsp__DataImport__c> processedImportsById =
            new Map<Id, npsp__DataImport__c>([
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :stagedImports
            ]);

        for (npsp__DataImport__c stagedImport : stagedImports) {
            npsp__DataImport__c processedImport =
                processedImportsById.get(stagedImport.Id);

            ImportResult result = new ImportResult();
            result.success =
                processedImport != null &&
                'Imported'.equalsIgnoreCase(processedImport.npsp__Status__c);

            if (processedImport != null) {
                result.contactId =
                    processedImport.npsp__Contact1Imported__c;
                result.opportunityId =
                    processedImport.npsp__DonationImported__c;

                if (!result.success) {
                    result.errorMessage =
                        processedImport.npsp__FailureInformation__c;
                }
            }

            results.add(result);
        }

        return results;
    }
}
