public inherited sharing class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> requestedPairKeys = new Set<String>();

        for (SoftCreditRequest request : requests) {
            if (request == null) {
                throw new SoftCreditException(
                    'A soft credit request cannot be null.'
                );
            }
            if (request.opportunityId == null) {
                throw new SoftCreditException(
                    'Each soft credit request must specify an opportunity.'
                );
            }
            if (request.contactId == null) {
                throw new SoftCreditException(
                    'Each soft credit request must specify a contact.'
                );
            }
            if (request.amount == null || request.amount <= 0) {
                throw new SoftCreditException(
                    'Each partial soft credit amount must be positive.'
                );
            }

            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
            requestedPairKeys.add(
                pairKey(request.opportunityId, request.contactId)
            );
        }

        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]);

        /*
         * Complete all required validation before performing any DML.
         */
        for (SoftCreditRequest request : requests) {
            Opportunity opportunity =
                opportunitiesById.get(request.opportunityId);

            if (opportunity == null) {
                throw new SoftCreditException(
                    'Opportunity is unavailable: ' +
                    String.valueOf(request.opportunityId)
                );
            }
            if (opportunity.npsp__Primary_Contact__c == request.contactId) {
                throw new SoftCreditException(
                    'The opportunity primary contact cannot receive a partial soft credit.'
                );
            }
            if (opportunity.Amount == null ||
                request.amount > opportunity.Amount) {
                throw new SoftCreditException(
                    'A partial soft credit amount cannot exceed the opportunity amount.'
                );
            }
        }

        Map<String, OpportunityContactRole> selectedRolesByPair =
            new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> duplicateRoles =
            new List<OpportunityContactRole>();

        for (OpportunityContactRole contactRole : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
              AND ContactId IN :contactIds
            ORDER BY CreatedDate, Id
        ]) {
            String key = pairKey(
                contactRole.OpportunityId,
                contactRole.ContactId
            );

            if (!requestedPairKeys.contains(key)) {
                continue;
            }

            if (selectedRolesByPair.containsKey(key)) {
                duplicateRoles.add(contactRole);
            } else {
                selectedRolesByPair.put(key, contactRole);
            }
        }

        List<OpportunityContactRole> rolesToUpsert =
            new List<OpportunityContactRole>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(
                request.opportunityId,
                request.contactId
            );
            OpportunityContactRole contactRole =
                selectedRolesByPair.get(key);

            if (contactRole == null) {
                contactRole = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId
                );
                selectedRolesByPair.put(key, contactRole);
            }

            contactRole.Role = request.role;
            rolesToUpsert.add(contactRole);
        }

        if (!duplicateRoles.isEmpty()) {
            delete duplicateRoles;
        }

        /*
         * Mixed upsert updates existing roles and inserts missing roles,
         * populating IDs needed by the partial soft credits.
         */
        upsert rolesToUpsert;

        /*
         * Query after contact-role DML so any records affected by NPSP
         * automation are included.
         */
        Map<String, npsp__Partial_Soft_Credit__c> selectedCreditsByPair =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> duplicateCredits =
            new List<npsp__Partial_Soft_Credit__c>();

        for (npsp__Partial_Soft_Credit__c softCredit : [
            SELECT Id,
                   npsp__Opportunity__c,
                   npsp__Contact__c,
                   npsp__Amount__c,
                   npsp__Role_Name__c,
                   npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact__c IN :contactIds
            ORDER BY CreatedDate, Id
        ]) {
            String key = pairKey(
                softCredit.npsp__Opportunity__c,
                softCredit.npsp__Contact__c
            );

            if (!requestedPairKeys.contains(key)) {
                continue;
            }

            if (selectedCreditsByPair.containsKey(key)) {
                duplicateCredits.add(softCredit);
            } else {
                selectedCreditsByPair.put(key, softCredit);
            }
        }

        if (!duplicateCredits.isEmpty()) {
            delete duplicateCredits;
        }

        List<npsp__Partial_Soft_Credit__c> creditsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(
                request.opportunityId,
                request.contactId
            );
            OpportunityContactRole contactRole =
                selectedRolesByPair.get(key);
            npsp__Partial_Soft_Credit__c softCredit =
                selectedCreditsByPair.get(key);

            if (softCredit == null) {
                softCredit = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = request.opportunityId,
                    npsp__Contact__c = request.contactId
                );
            }

            softCredit.npsp__Amount__c = request.amount;
            softCredit.npsp__Role_Name__c = request.role;
            softCredit.npsp__Contact_Role_ID__c =
                String.valueOf(contactRole.Id);

            creditsToUpsert.add(softCredit);
        }

        upsert creditsToUpsert;
    }

    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) +
            ':' +
            String.valueOf(contactId);
    }
}
